static uint32_t encoded_rol(uint32_t value, uint32_t count) {
  uint32_t decoded = value * UINT32_C(0x8fa491df);
  uint32_t shift = count & 31;

  return (decoded << shift) | (decoded >> ((32 - shift) & 31));
}

