static uint32_t hash_preprocess_word(uint32_t input) {
  const uint32_t input_multiplier = UINT32_C(0xa272be3f);
  const uint32_t combine_multiplier = UINT32_C(0x7f8631bf);
  const uint32_t byte_multiplier = UINT32_C(0xc83bebc7);
  const uint32_t word_bias = UINT32_C(0x44e57c7e);
  uint32_t byte0 = hash_byte_table_0[input & 0xff];
  uint32_t byte1 = hash_byte_table_1[(input >> 8) & 0xff];
  uint32_t byte2 = hash_byte_table_2[(input >> 16) & 0xff];
  uint32_t byte3 = hash_byte_table_3[input >> 24];
  uint32_t high_mask;
  uint32_t partial;
  uint32_t scaled;

  scaled = (((byte0 * UINT32_C(0xc9) * UINT32_C(0x79)) & 0xff) << 8) * input_multiplier;

  byte1 = byte1 * UINT32_C(0xc9) & 0xff;
  high_mask = ~(byte1 * UINT32_C(0x79)) | 0xff;
  partial = byte1 * byte_multiplier + word_bias + ~high_mask * input_multiplier + high_mask * word_bias + scaled;
  scaled = partial * combine_multiplier * UINT32_C(0x100) * input_multiplier;

  high_mask = ~(byte2 * UINT32_C(0x79)) | 0xff;
  partial = byte2 * byte_multiplier + word_bias + ~high_mask * input_multiplier + high_mask * word_bias + partial + scaled;

  high_mask = ~(byte3 * UINT32_C(0x79)) | 0xff;
  partial = high_mask * word_bias + byte3 * byte_multiplier + word_bias + ~high_mask * input_multiplier + partial * combine_multiplier * UINT32_C(0x100) * input_multiplier + partial;

  partial = partial * combine_multiplier * UINT32_C(0x100) * input_multiplier + partial;
  return partial * combine_multiplier;
}

static uint8_t hash_byte_index(uint32_t value) {
  return (uint8_t)(value * UINT32_C(0xbf));
}

static uint32_t hash_state_to_word(uint32_t canonical_state_word) {
  const uint32_t state_encode_multiplier = UINT32_C(0xc2ed397f);
  const uint32_t input_multiplier = UINT32_C(0xa272be3f);
  const uint32_t index_decode = UINT32_C(0x7f8631bf);
  const uint32_t index_multiplier = UINT32_C(0x5d8d41c1);
  const uint32_t state_multiplier = UINT32_C(0xbcb95b41);
  const uint32_t byte_multiplier = UINT32_C(0xc83bebc7);
  const uint32_t word_bias = UINT32_C(0x44e57c7e);
  const uint32_t rotate_input = UINT32_C(0x1e051c21);
  const uint32_t encoded_or_multiplier = UINT32_C(0x00f39c82);
  uint32_t mapped;
  uint32_t high_mask;
  uint32_t rotated;
  uint32_t combined;
  uint32_t state_word = canonical_state_word * state_encode_multiplier;

  mapped = hash_byte_table_0[hash_byte_index(state_word * state_multiplier)];
  mapped = mapped * UINT32_C(0xc9) & 0xff;
  high_mask = ~(mapped * UINT32_C(0x79)) | 0xff;
  combined = state_word * state_multiplier + high_mask * word_bias + mapped * byte_multiplier + word_bias + ~high_mask * input_multiplier;
  rotated = encoded_rol(combined * rotate_input, 11);
  rotated *= input_multiplier;

  mapped = hash_byte_table_1[hash_byte_index(rotated)];
  mapped = mapped * UINT32_C(0xc9) & 0xff;
  high_mask = ~(mapped * UINT32_C(0x79)) | 0xff;
  combined = ~high_mask * input_multiplier + mapped * byte_multiplier + word_bias + high_mask * word_bias;
  rotated = encoded_rol((((combined * encoded_or_multiplier - 1) | (rotated * encoded_or_multiplier - 1)) * input_multiplier + rotated + combined - index_multiplier) * rotate_input, 10);

  mapped = hash_byte_table_2[hash_byte_index(rotated * input_multiplier)];
  high_mask = ~(mapped * UINT32_C(0x79)) | 0xff;
  combined = mapped * byte_multiplier + word_bias + ~high_mask * input_multiplier + high_mask * word_bias;
  rotated = encoded_rol((rotated * input_multiplier - combined) * rotate_input, 7);
  return rotated * input_multiplier * index_decode;
}

static void hash_final(const uint32_t state[16], uint8_t output[32]) {
  for (size_t i = 0; i < 8; i++) {
    uint32_t value = state[8 + i] * UINT32_C(0xf46ef4ff);
    store32_le(output + i * 4, value);
  }
}

int hash(uint8_t work[64], uint8_t output[32]) {
  EdonR256State edon_r_state;
  uint32_t* state;
  uint32_t block[16];

  if (work == NULL || output == NULL) {
    return -1;
  }

  for (size_t i = 0; i < 16; i++) {
    block[i] = hash_preprocess_word(load32_le(work + i * 4));
  }
  EdonR256Init(&edon_r_state);
  state = edon_r_state.hash;

  for (size_t round = 0; round < 4; round++) {
    EdonR256Compress(&edon_r_state, block);
    if (round != 3) {
      for (size_t i = 0; i < 16; i++) {
        block[i] = hash_state_to_word(state[i]);
      }
    }
  }

  for (size_t i = 0; i < 16; i++) {
    store32_le(work + i * 4, block[i]);
  }
  hash_final(state, output);
  return 0;
}
